import { apiKeyClientProjectionToValue } from './api-key-client.model';
import { ComponentFixture, TestBed } from '@angular/core/testing';
import {
  InteractionMocks,
  RepositoryMock,
  allow,
  configureFeatureTesting,
  createWithoutTemplate,
  internals,
  mockRepository,
  mockTick,
  moduleCompiles,
} from 'app/shared/testing/feature-testing';

describe('apiKeyClientProjectionToValue', () => {
  const value = {
    uid: 'value-uid',
    code: 'value-code',
    key: 'value-key',
    enabled: 'value-enabled',
    scopes: 'value-scopes',
    version: 'value-version',
  } as any;

  it('returns null without projection', () => {
    expect(apiKeyClientProjectionToValue(null)).toBeNull();
    expect(apiKeyClientProjectionToValue(undefined)).toBeNull();
  });

  it('keeps a plain value', () => {
    expect(apiKeyClientProjectionToValue(value)).toEqual(value);
  });

  it('reduces the projected references to their key', () => {
    const projection = {
      uid: 'value-uid',
      code: 'value-code',
      key: 'value-key',
      enabled: 'value-enabled',
      scopes: 'value-scopes',
      version: 'value-version',
    } as any;
    expect(apiKeyClientProjectionToValue(projection)).toEqual(value);
  });
});
